const darkTheme=document.documentElement.dataset.theme,darkSkin=document.documentElement.dataset.skin;
const R=window.REFERENCE,pop=document.querySelector('#reference-pop');
const $=s=>document.querySelector(s),all=s=>[...document.querySelectorAll(s)];
const state={create:{repeat:null,reminder:null},issue:{repeat:null,reminder:null}};
let view='create',anchor=null,panel=null,draft=null,calendarFor=null,chosenDay='2026-10-12',month=9,year=2026;
const now=new Date(R.baseClock),zone='Asia/Tashkent';
const dateShort=date=>new Intl.DateTimeFormat('ru',{timeZone:zone,day:'numeric',month:'short'}).format(new Date(date));
const dateTime=date=>new Intl.DateTimeFormat('ru',{timeZone:zone,day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}).format(new Date(date));
const iso=d=>d.toISOString().slice(0,10),fromDay=(day,time='09:00')=>new Date(day+'T'+time+':00+05:00');
const today='2026-10-11',base=()=>({kind:'weekly',every:1,days:[1],start:'2026-10-12',time:'09:00',monthDay:12,skip:false});
$('#create-view .form-disclosure').insertAdjacentHTML('beforebegin',R.row);
$('#issue-view .issue-heading').insertAdjacentHTML('beforeend','<div class="ref-task-automation"></div>');
all('#create-view .ds-dialog-foot button').find(b=>b.textContent.includes('Создать задачу')).addEventListener('click',event=>{event.preventDefault();message('Это макет: задачи и расписание на стенде не сохраняются.')});
$('#issue-view .issue-details-toggle')?.addEventListener('click',event=>{const el=$('#issue-view .issue-secondary-properties'),on=!el.hasAttribute('data-expanded');el.toggleAttribute('data-expanded',on);event.currentTarget.setAttribute('aria-expanded',String(on))});
$('#issue-view .issue-toolbar-actions button[aria-label="Действия"]').addEventListener('click',e=>open('actions',e.currentTarget));
all('[data-view]').forEach(b=>b.addEventListener('click',()=>{hide(false);view=b.dataset.view;$('#create-view').hidden=view!=='create';$('#issue-view').hidden=view!=='issue';all('[data-view]').forEach(v=>v.setAttribute('aria-pressed',String(v.dataset.view===view)));renderState()}));
$('#theme-toggle').addEventListener('click',e=>{const light=document.documentElement.dataset.theme!=='light';document.documentElement.dataset.theme=light?'light':darkTheme;if(light)document.documentElement.removeAttribute('data-skin');else if(darkSkin)document.documentElement.dataset.skin=darkSkin;e.currentTarget.textContent=light?'Тёмная тема':'Светлая тема'});
all('[data-open]').forEach(b=>b.addEventListener('click',()=>open(b.dataset.open,b)));
function message(text){const el=$('#preview-message');el.textContent=text;el.hidden=false;setTimeout(()=>el.hidden=true,4200)}
function summary(r){if(!r)return'Не повторять';const weekday=['','Пн','Вт','Ср','Чт','Пт','Сб','Вс'];return (r.kind==='daily'?(r.every===1?'Каждый день':'Каждые '+r.every+' дн.'):r.kind==='weekly'?(r.every===1?r.days.map(d=>weekday[d]).join(', '):'Каждые '+r.every+' нед.'):'Каждые '+r.every+' мес., '+r.monthDay+' числа')+' · '+r.time}
function renderState(){for(const [kind,attribute]of[['repeat','data-repeat-summary'],['reminder','data-reminder-summary']]){const val=state[view][kind],button=$('#create-view [data-open='+kind+']');button.toggleAttribute('data-selected',!!state.create[kind]);$('#create-view ['+attribute+']').textContent=kind==='repeat'?summary(state.create.repeat):(state.create.reminder?dateTime(state.create.reminder):'Не задано')}
 const chips=$('#issue-view .ref-task-automation');chips.innerHTML=[state.issue.repeat?'<button type="button" class="ref-task-chip ds-focus" data-open="repeat">'+R.icons.repeat+summary(state.issue.repeat)+'</button>':'',state.issue.reminder?'<button type="button" class="ref-task-chip ds-focus" data-open="reminder">'+R.icons.bell+'Напомнить '+dateTime(state.issue.reminder)+'</button>':''].join('');chips.querySelectorAll('[data-open]').forEach(b=>b.addEventListener('click',()=>open(b.dataset.open,b)))}
function hide(focus=true){if(pop.matches(':popover-open'))pop.hidePopover();if(anchor){anchor.setAttribute('aria-expanded','false');anchor.removeAttribute('aria-controls');if(focus&&anchor.isConnected)anchor.focus()}panel=null}
function position(){if(!anchor)return;const box=anchor.getBoundingClientRect(),size=pop.getBoundingClientRect(),zoom=parseFloat(getComputedStyle(document.documentElement).zoom)||1;const x=Math.max(12,Math.min(innerWidth-size.width-12,box.right-size.width)),y=Math.max(12,Math.min(innerHeight-size.height-12,box.bottom+8));pop.style.left=x/zoom+'px';pop.style.top=y/zoom+'px'}
function open(kind,el){hide(false);anchor=el;panel=kind;anchor.setAttribute('aria-expanded','true');anchor.setAttribute('aria-haspopup',kind==='actions'?'menu':'dialog');anchor.setAttribute('aria-controls','reference-pop');pop.dataset.panel=kind;pop.setAttribute('role',kind==='actions'?'menu':'dialog');pop.setAttribute('aria-label',kind==='actions'?'Действия':kind==='repeat'?'Повторение задачи':kind==='calendar'?'Дата и время напоминания':'Напомнить мне');
 if(kind==='repeat'){draft=structuredClone(state[view].repeat??base());pop.innerHTML=R.repeat;wireRepeat();}
 else if(kind==='reminder'){pop.innerHTML=R.reminder;wireReminder();}
 else if(kind==='actions'){pop.innerHTML='<div class="ref-menu"><button type="button" role="menuitem" class="ds-menu-item" data-menu-open="reminder">'+R.icons.bell+'<span class="flex-1 text-left">Напомнить мне</span>'+R.icons.chev+'</button><button type="button" role="menuitem" class="ds-menu-item" data-menu-open="repeat">'+R.icons.repeat+'<span class="flex-1 text-left">Повторять задачу</span>'+R.icons.chev+'</button><div role="separator" class="ds-menu-sep"></div>'+R.menu+'</div>';pop.querySelectorAll('[data-menu-open]').forEach(b=>b.addEventListener('click',()=>open(b.dataset.menuOpen,el)));pop.querySelectorAll('[role=menuitem]:not([data-menu-open])').forEach(b=>b.addEventListener('click',()=>hide()));}
 pop.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',()=>hide()));if(!pop.matches(':popover-open'))pop.showPopover();position();pop.querySelector(kind==='repeat'?'#repeat-every':kind==='actions'?'[role=menuitem]':'#reminder-presets button')?.focus();}
function wireRepeat(){all('#reference-pop [data-kind]').forEach(b=>b.addEventListener('click',()=>{draft.kind=b.dataset.kind;draft.every=1;updateRepeat()}));$('#repeat-every').value=draft.every;$('#repeat-time').value=draft.time;$('#month-day').value=draft.monthDay;$('#skip-open').checked=draft.skip;
 for(const [selector,key]of[['#repeat-every','every'],['#month-day','monthDay'],['#repeat-time','time']])$(selector).addEventListener('input',e=>{draft[key]=key==='time'?e.target.value:Number(e.target.value);updateRepeat()});$('#skip-open').addEventListener('change',e=>draft.skip=e.target.checked);
 all('#reference-pop [data-day]').forEach(b=>b.addEventListener('click',()=>{const d=Number(b.dataset.day);draft.days=draft.days.includes(d)?draft.days.filter(x=>x!==d):[...draft.days,d].sort();updateRepeat()}));
 $('#repeat-date').addEventListener('click',()=>openCalendar('repeat',draft.start));
 $('#repeat-apply').addEventListener('click',()=>{state[view].repeat=structuredClone(draft);renderState();hide()});$('#repeat-clear').addEventListener('click',()=>{state[view].repeat=null;renderState();hide()});updateRepeat();}
function updateRepeat(){all('#reference-pop [data-kind]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.kind===draft.kind)));$('#weekly-days').hidden=draft.kind!=='weekly';$('#monthly-day').hidden=draft.kind!=='monthly';all('#reference-pop [data-day]').forEach(b=>b.setAttribute('aria-pressed',String(draft.days.includes(Number(b.dataset.day)))));$('#repeat-every').value=draft.every;$('#repeat-every').max=draft.kind==='daily'?30:12;$('#repeat-unit').textContent=draft.kind==='daily'?'дн.':draft.kind==='weekly'?'нед.':'мес.';$('#repeat-date').innerHTML=dateShort(fromDay(draft.start))+' '+new Date(draft.start+'T00:00:00Z').getUTCFullYear()+' '+R.icons.chev;
 const valid=Number.isInteger(draft.every)&&draft.every>=1&&draft.every<=(draft.kind==='daily'?30:12)&&(draft.kind!=='weekly'||draft.days.length>0)&&/^\d{2}:\d{2}$/.test(draft.time)&&draft.monthDay>=1&&draft.monthDay<=31;
 $('#repeat-apply').disabled=!valid;$('#next-dates').textContent=valid?nextDates(draft).map(dateShort).join(' · '):'Укажите корректный интервал и дни';position();}
function nextDates(r){const first=new Date(r.start+'T00:00:00Z'),found=[],originMonday=new Date(first);originMonday.setUTCDate(first.getUTCDate()-((first.getUTCDay()+6)%7));for(let n=0;n<1200&&found.length<3;n++){const d=new Date(first);d.setUTCDate(first.getUTCDate()+n);let match=r.kind==='daily'?n%r.every===0:r.kind==='weekly'?Math.floor((d-originMonday)/604800000)%r.every===0&&r.days.includes(d.getUTCDay()||7):((d.getUTCFullYear()-first.getUTCFullYear())*12+d.getUTCMonth()-first.getUTCMonth())%r.every===0&&d.getUTCDate()===r.monthDay;if(match)found.push(fromDay(iso(d),r.time))}return found}
function presets(){const tomorrow=fromDay('2026-10-12'),due=R.task.dueDate?new Date(R.task.dueDate+'T00:00:00Z'):null;if(due)due.setUTCDate(due.getUTCDate()-1);return[['Через час',new Date(now.getTime()+3600000)],['Через 3 часа',new Date(now.getTime()+10800000)],['Сегодня вечером',fromDay(today,'18:00')],['Завтра утром',tomorrow],['Через неделю',fromDay('2026-10-18')],['Через месяц',fromDay('2026-11-11')],['За день до срока',due?fromDay(iso(due)):null]]}
function wireReminder(){const list=$('#reminder-presets');list.innerHTML=presets().map(([label,date])=>'<button type="button" class="ds-focus" data-preset="'+label+'"'+(!date||date<=now?' aria-disabled="true"':'')+'>'+R.icons.clock+'<span>'+label+'</span><small>'+(date?dateTime(date):'Нет срока')+'</small></button>').join('');presets().forEach(([label,date])=>list.querySelector('[data-preset="'+label+'"]').addEventListener('click',()=>{if(!date||date<=now)return;state[view].reminder=date.toISOString();renderState();hide()}));$('#reminder-custom').addEventListener('click',()=>openCalendar('reminder','2026-10-15'));$('#reminder-clear').addEventListener('click',()=>{state[view].reminder=null;renderState();hide()})}
function openCalendar(kind,day){calendarFor=kind;chosenDay=day;const d=new Date(day+'T00:00:00Z');month=d.getUTCMonth();year=d.getUTCFullYear();panel='calendar';pop.dataset.panel='calendar';pop.setAttribute('aria-label',kind==='repeat'?'Первый повтор':'Дата и время напоминания');pop.innerHTML=R.calendar;$('#custom-time-row').hidden=kind==='repeat';$('#custom-time').value='09:00';$('#calendar-title').textContent=kind==='repeat'?'Первый повтор':'Дата и время';pop.querySelector('[data-back]').addEventListener('click',()=>back());$('#calendar-prev').addEventListener('click',()=>{month--;if(month<0){month=11;year--}drawCalendar()});$('#calendar-next').addEventListener('click',()=>{month++;if(month>11){month=0;year++}drawCalendar()});$('#calendar-apply').addEventListener('click',()=>{if(kind==='repeat'){draft.start=chosenDay;back()}else{const date=fromDay(chosenDay,$('#custom-time').value);if(date<=now){$('#custom-error').hidden=false;return}state[view].reminder=date.toISOString();renderState();hide()}});drawCalendar();pop.querySelector('[aria-pressed=true]')?.focus();}
function back(){if(calendarFor==='repeat'){panel='repeat';pop.dataset.panel='repeat';pop.innerHTML=R.repeat;wireRepeat();pop.querySelector('[data-close]').addEventListener('click',()=>hide());position();$('#repeat-date').focus()}else open('reminder',anchor)}
function drawCalendar(){const first=new Date(Date.UTC(year,month,1)),count=new Date(Date.UTC(year,month+1,0)).getUTCDate(),offset=(first.getUTCDay()+6)%7;$('#calendar-month').textContent=new Intl.DateTimeFormat('ru',{month:'long',year:'numeric',timeZone:'UTC'}).format(first);let html='<span></span>'.repeat(offset);for(let day=1;day<=count;day++){const key=iso(new Date(Date.UTC(year,month,day)));html+='<button type="button" class="ds-focus" data-date="'+key+'" aria-label="'+dateShort(fromDay(key))+'" aria-pressed="'+(key===chosenDay)+'"'+(key<today?' disabled':'')+'>'+day+'</button>'}$('#calendar-grid').innerHTML=html;pop.querySelectorAll('[data-date]').forEach(b=>b.addEventListener('click',()=>{chosenDay=b.dataset.date;drawCalendar();pop.querySelector('[data-date="'+chosenDay+'"]')?.focus()}));position();}
window.addEventListener('resize',position);document.addEventListener('pointerdown',e=>{if(panel&&!pop.contains(e.target)&&!anchor?.contains(e.target))hide(false)});document.addEventListener('keydown',e=>{if(!panel)return;if(e.key==='Escape'){e.preventDefault();panel==='calendar'?back():hide();return}if(panel==='actions'&&['ArrowDown','ArrowUp','Home','End'].includes(e.key)){const items=[...pop.querySelectorAll('[role=menuitem]:not([aria-disabled=true])')],i=items.indexOf(document.activeElement),n=e.key==='Home'?0:e.key==='End'?items.length-1:e.key==='ArrowDown'?(i+1)%items.length:(i-1+items.length)%items.length;e.preventDefault();items[n]?.focus()}});
renderState();
